    float pre = (arc_spiral_a + (arc_spiral_b * th) / (2 * M_PI));
    points.at(i-init_theta).header.frame_id = MAP;
    points.at(i-init_theta).point.x = pre * cos(th);
    points.at(i-init_theta).point.y = pre * sin(th);
  }
  return points;
}

